program nullify_02
implicit none

   real, pointer :: p1
   real, target :: t1 
   integer, pointer :: p2
   integer, target :: t2
   
   p1=>t1
   p1 = 1
   p2=>t2
   p2 = 2.
   nullify(p1, p2) 
   
   
end program nullify_02
 aditya-trivedi   lfortran    fortran ≢    lfortran ./integration_tests/nullify_02.f90 --show-fortran --show-stacktrace
program nullify_02
implicit none
real(4), pointer :: p1
integer(4), pointer :: p2
real(4) :: t1
integer(4) :: t2
p1 => t1
p1 = real(1, kind=4)
p2 => t2
p2 = int(2.00000000e+00, kind=4)
nullify (p1, p2)
end program nullify_02
