Consider the below C++ code:
```cpp
#include <iostream>

int main() {
    int* p1 = nullptr; 
    int* p2 = nullptr;
    int t1;
    int t2;

    p1 = &t1; 
    p2 = &t1;

    *p1 = 1;

    p1 = nullptr;
    p2 = nullptr;


    if (p1 == nullptr && p2 == nullptr) {
        std::cout << "p1 and p2 are nullified." << std::endl;
    }

    return 0;
}
